def shell_sort(my_list):
    gap = len(my_list) // 2
    while gap > 0:
        for i in range(gap, len(my_list)):
            current_element = my_list[i]
            j = i
            while j >= gap and my_list[j - gap] > current_element:
                my_list[j] = my_list[j - gap]
                j -= gap
            my_list[j] = current_element
        gap = gap // 2
    return my_list

